package com.pluginhotkeys;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Plugin Hotkeys",
	description = "Bind a hotkey to any installed plugin to switch it on or off.",
	tags = {"hotkey", "toggle", "enable", "disable", "plugin", "keybind"}
)
public class PluginHotkeysPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(PluginHotkeysPlugin.class);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private PluginHotkeysConfig config;

	private final List<HotkeyListener> listeners = new ArrayList<>();

	@Provides
	PluginHotkeysConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PluginHotkeysConfig.class);
	}

	@Override
	protected void startUp()
	{
		for (int slot = 1; slot <= PluginHotkeysConfig.SLOTS; slot++)
		{
			final int s = slot;
			HotkeyListener listener = new HotkeyListener(() -> slotKeybind(s))
			{
				@Override
				public void hotkeyPressed()
				{
					toggleSlot(s);
				}
			};
			listeners.add(listener);
			keyManager.registerKeyListener(listener);
		}
	}

	@Override
	protected void shutDown()
	{
		for (HotkeyListener listener : listeners)
		{
			keyManager.unregisterKeyListener(listener);
		}
		listeners.clear();
	}

	private Keybind slotKeybind(int slot)
	{
		Keybind keybind = configManager.getConfiguration(PluginHotkeysConfig.GROUP, "key" + slot, Keybind.class);
		return keybind == null ? Keybind.NOT_SET : keybind;
	}

	private String slotPluginName(int slot)
	{
		return configManager.getConfiguration(PluginHotkeysConfig.GROUP, "plugin" + slot);
	}

	private void toggleSlot(int slot)
	{
		List<String> queries = ToggleLogic.splitQueries(slotPluginName(slot));
		if (queries.isEmpty())
		{
			return;
		}

		// Hotkeys arrive on the Swing event thread, which is where PluginManager insists plugins are
		// started and stopped from (the plugin list does the same).
		SwingUtilities.invokeLater(() -> toggle(queries));
	}

	private void toggle(List<String> queries)
	{
		List<Plugin> candidates = new ArrayList<>();
		List<String> names = new ArrayList<>();
		for (Plugin plugin : pluginManager.getPlugins())
		{
			PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			if (plugin == this || descriptor == null || descriptor.hidden())
			{
				continue;
			}
			candidates.add(plugin);
			names.add(plugin.getName());
		}

		// Work out every plugin the slot refers to first, remembering the names that didn't resolve.
		List<Plugin> targets = new ArrayList<>();
		List<String> notes = new ArrayList<>();
		for (String query : queries)
		{
			PluginNameMatcher.Result result = PluginNameMatcher.find(names, query);
			if (result.kind == PluginNameMatcher.Kind.NOT_FOUND)
			{
				notes.add("No installed plugin matches \"" + query + "\".");
			}
			else if (result.kind == PluginNameMatcher.Kind.AMBIGUOUS)
			{
				notes.add("\"" + query + "\" matches more than one plugin (" + String.join(", ", result.candidates) + "), type more of the name.");
			}
			else if (!targets.contains(candidates.get(result.index)))
			{
				targets.add(candidates.get(result.index));
			}
		}

		boolean[] active = new boolean[targets.size()];
		for (int i = 0; i < active.length; i++)
		{
			active[i] = pluginManager.isPluginActive(targets.get(i));
		}
		boolean[] desired = ToggleLogic.desiredStates(active, config.multiPluginMode());

		List<String> enabled = new ArrayList<>();
		List<String> disabled = new ArrayList<>();
		for (int i = 0; i < targets.size(); i++)
		{
			Plugin target = targets.get(i);
			if (desired[i] == active[i])
			{
				continue;
			}

			try
			{
				pluginManager.setPluginEnabled(target, desired[i]);
				if (desired[i])
				{
					pluginManager.startPlugin(target);
					enabled.add(target.getName());
				}
				else
				{
					pluginManager.stopPlugin(target);
					disabled.add(target.getName());
				}
			}
			catch (PluginInstantiationException ex)
			{
				log.warn("Couldn't {} {}", desired[i] ? "start" : "stop", target.getName(), ex);
				notes.add("Couldn't " + (desired[i] ? "start " : "stop ") + target.getName() + ", see the log for details.");
			}
		}

		if (!enabled.isEmpty())
		{
			notes.add(0, "Enabled " + String.join(", ", enabled) + ".");
		}
		if (!disabled.isEmpty())
		{
			notes.add(enabled.isEmpty() ? 0 : 1, "Disabled " + String.join(", ", disabled) + ".");
		}
		if (!notes.isEmpty())
		{
			say(String.join(" ", notes));
		}
	}

	private void say(String text)
	{
		if (!config.chatMessage())
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage("Plugin Hotkeys: " + text)
				.build());
		});
	}
}

package com.pluginhotkeys;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Finds the plugin a typed name refers to. Matching ignores case and punctuation, and tries, in order:
 * the whole name, then names that start with the text, then names that contain it. The first tier with
 * any hit decides, so "ground" can't be hijacked by a longer name once "Ground Items" starts with it,
 * but two plugins in the same tier make the text ambiguous rather than picking one for you.
 */
final class PluginNameMatcher
{
	enum Kind
	{
		NOT_FOUND,
		FOUND,
		AMBIGUOUS
	}

	static final class Result
	{
		final Kind kind;
		/** Index into the searched names; only meaningful when kind is FOUND. */
		final int index;
		/** Every name in the deciding tier; only meaningful when kind is AMBIGUOUS. */
		final List<String> candidates;

		private Result(Kind kind, int index, List<String> candidates)
		{
			this.kind = kind;
			this.index = index;
			this.candidates = candidates;
		}
	}

	static Result find(List<String> names, String query)
	{
		String wanted = normalize(query);
		if (wanted.isEmpty())
		{
			return new Result(Kind.NOT_FOUND, -1, new ArrayList<>());
		}

		List<String> normalized = new ArrayList<>(names.size());
		for (String name : names)
		{
			normalized.add(normalize(name));
		}

		for (int tier = 0; tier < 3; tier++)
		{
			List<Integer> hits = new ArrayList<>();
			for (int i = 0; i < normalized.size(); i++)
			{
				String candidate = normalized.get(i);
				boolean hit = tier == 0 ? candidate.equals(wanted)
					: tier == 1 ? candidate.startsWith(wanted)
					: candidate.contains(wanted);
				if (hit)
				{
					hits.add(i);
				}
			}

			if (hits.size() == 1 || (tier == 0 && !hits.isEmpty()))
			{
				return new Result(Kind.FOUND, hits.get(0), new ArrayList<>());
			}
			if (hits.size() > 1)
			{
				List<String> candidates = new ArrayList<>();
				for (int i : hits)
				{
					candidates.add(names.get(i));
				}
				return new Result(Kind.AMBIGUOUS, -1, candidates);
			}
		}

		return new Result(Kind.NOT_FOUND, -1, new ArrayList<>());
	}

	/** Lower case, letters and digits only, single spaces. */
	static String normalize(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", " ").trim();
	}

	private PluginNameMatcher()
	{
	}
}

package com.pluginhotkeys;

import java.util.ArrayList;
import java.util.List;

final class ToggleLogic
{
	/** Splits "a, b,,c" into the non-blank names a, b, c. */
	static List<String> splitQueries(String text)
	{
		List<String> queries = new ArrayList<>();
		if (text == null)
		{
			return queries;
		}
		for (String part : text.split(","))
		{
			if (!PluginNameMatcher.normalize(part).isEmpty())
			{
				queries.add(part.trim());
			}
		}
		return queries;
	}

	/**
	 * @param active whether each plugin is currently running, in the order they were listed
	 * @return whether each plugin should be running after the press. SYNC follows the first plugin, so the
	 * whole list goes on if it was off and off if it was on; FLIP swaps every plugin on its own.
	 */
	static boolean[] desiredStates(boolean[] active, MultiPluginMode mode)
	{
		boolean[] desired = new boolean[active.length];
		for (int i = 0; i < active.length; i++)
		{
			desired[i] = mode == MultiPluginMode.SYNC ? !active[0] : !active[i];
		}
		return desired;
	}

	private ToggleLogic()
	{
	}
}

package com.pluginhotkeys;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class PluginNameMatcherTest
{
	private static final List<String> NAMES = Arrays.asList(
		"Ground Items", "Ground Markers", "[S] Npc Notifier", "NPC Indicators", "Swing Rainbow", "XP Tracker");

	@Test
	public void exactNameIgnoresCaseAndPunctuation()
	{
		PluginNameMatcher.Result r = PluginNameMatcher.find(NAMES, "swing-rainbow");

		assertEquals(PluginNameMatcher.Kind.FOUND, r.kind);
		assertEquals(4, r.index);
	}

	@Test
	public void uniqueStartIsEnough()
	{
		PluginNameMatcher.Result r = PluginNameMatcher.find(NAMES, "xp");

		assertEquals(PluginNameMatcher.Kind.FOUND, r.kind);
		assertEquals(5, r.index);
	}

	@Test
	public void uniqueContainsFindsNamesWithADecoratedPrefix()
	{
		PluginNameMatcher.Result r = PluginNameMatcher.find(NAMES, "npc notifier");

		assertEquals(PluginNameMatcher.Kind.FOUND, r.kind);
		assertEquals(2, r.index);
	}

	@Test
	public void twoPluginsInTheDecidingTierIsAmbiguous()
	{
		PluginNameMatcher.Result r = PluginNameMatcher.find(NAMES, "ground");

		assertEquals(PluginNameMatcher.Kind.AMBIGUOUS, r.kind);
		assertEquals(Arrays.asList("Ground Items", "Ground Markers"), r.candidates);
	}

	@Test
	public void anExactNameWinsEvenWhenLongerNamesStartWithIt()
	{
		List<String> names = Arrays.asList("Ground Items Plus", "Ground Items");

		PluginNameMatcher.Result r = PluginNameMatcher.find(names, "ground items");

		assertEquals(PluginNameMatcher.Kind.FOUND, r.kind);
		assertEquals(1, r.index);
	}

	@Test
	public void startsWithOutranksContains()
	{
		// "npc" starts "NPC Indicators" but is only contained in "[S] Npc Notifier".
		PluginNameMatcher.Result r = PluginNameMatcher.find(NAMES, "npc");

		assertEquals(PluginNameMatcher.Kind.FOUND, r.kind);
		assertEquals(3, r.index);
	}

	@Test
	public void blankAndUnknownNamesAreNotFound()
	{
		assertEquals(PluginNameMatcher.Kind.NOT_FOUND, PluginNameMatcher.find(NAMES, "  ").kind);
		assertEquals(PluginNameMatcher.Kind.NOT_FOUND, PluginNameMatcher.find(NAMES, null).kind);
		assertEquals(PluginNameMatcher.Kind.NOT_FOUND, PluginNameMatcher.find(NAMES, "zzz").kind);
	}
}

package com.pluginhotkeys;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class ToggleLogicTest
{
	@Test
	public void splitsOnCommasAndDropsBlanks()
	{
		assertEquals(Arrays.asList("Ground Items", "xp tracker", "npc"), ToggleLogic.splitQueries(" Ground Items, xp tracker ,, ,npc,"));
		assertEquals(Arrays.asList("solo"), ToggleLogic.splitQueries("solo"));
		assertEquals(0, ToggleLogic.splitQueries("").size());
		assertEquals(0, ToggleLogic.splitQueries(null).size());
	}

	@Test
	public void syncFollowsTheFirstPluginWhenTheyDisagree()
	{
		// first is on, second is off: everything goes off
		assertArrayEquals(new boolean[]{false, false}, ToggleLogic.desiredStates(new boolean[]{true, false}, MultiPluginMode.SYNC));
		// first is off, second is on: everything goes on
		assertArrayEquals(new boolean[]{true, true}, ToggleLogic.desiredStates(new boolean[]{false, true}, MultiPluginMode.SYNC));
	}

	@Test
	public void flipSwapsEachPluginOnItsOwn()
	{
		assertArrayEquals(new boolean[]{false, true, false}, ToggleLogic.desiredStates(new boolean[]{true, false, true}, MultiPluginMode.FLIP));
	}

	@Test
	public void aSinglePluginBehavesTheSameInBothModes()
	{
		assertArrayEquals(new boolean[]{true}, ToggleLogic.desiredStates(new boolean[]{false}, MultiPluginMode.SYNC));
		assertArrayEquals(new boolean[]{true}, ToggleLogic.desiredStates(new boolean[]{false}, MultiPluginMode.FLIP));
	}
}
